<?php require_once __DIR__.'/includes/permissions.php'; require_permission('users.view'); $pdo=db(); $u=current_user(); $roles=$pdo->query('SELECT * FROM roles ORDER BY name')->fetchAll();$services=active_services();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action'); try {if($action==='save' && can('users.create')){$id=(int)post('id',0);$staff=trim((string)post('staff_id'));$name=trim((string)post('full_name'));$email=trim((string)post('email'));$role=(int)post('role_id');$service=post('service_id')!==''?(int)post('service_id'):null;$pw=(string)post('password');$ptype=trim((string)post('professional_type'));$lic=trim((string)post('license_no')); if(!$staff||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$role)throw new Exception('Please complete required fields.'); if($id){if($pw!==''){$s=$pdo->prepare('UPDATE users SET staff_id=?,full_name=?,email=?,role_id=?,service_id=?,professional_type=?,license_no=?,password_hash=? WHERE id=?');$s->execute([$staff,$name,$email,$role,$service,$ptype,$lic,password_hash($pw,PASSWORD_DEFAULT),$id]);}else{$s=$pdo->prepare('UPDATE users SET staff_id=?,full_name=?,email=?,role_id=?,service_id=?,professional_type=?,license_no=? WHERE id=?');$s->execute([$staff,$name,$email,$role,$service,$ptype,$lic,$id]);}audit('UPDATE','users',$id,'User updated');}else{if(strlen($pw)<8)throw new Exception('Password must be at least 8 characters.');$s=$pdo->prepare('INSERT INTO users(staff_id,full_name,email,password_hash,role_id,service_id,professional_type,license_no) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$staff,$name,$email,password_hash($pw,PASSWORD_DEFAULT),$role,$service,$ptype,$lic]);audit('CREATE','users',(int)$pdo->lastInsertId(),'User created');}flash('success','User saved successfully.');redirect(BASE_URL.'/users.php');}elseif($action==='toggle' && can('users.delete')){$id=(int)post('id');if($id===(int)$u['id'])throw new Exception('You cannot deactivate your own account.');$pdo->prepare('UPDATE users SET status=IF(status="Active","Inactive","Active") WHERE id=?')->execute([$id]);audit('UPDATE','users',$id,'User status changed');flash('success','User status updated.');redirect(BASE_URL.'/users.php');}}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query('SELECT u.*,r.name role_name,s.name service_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN services s ON s.id=u.service_id ORDER BY u.full_name')->fetchAll(); include __DIR__.'/includes/header.php'; ?><div class="page-head"><div><h1>Users & Staff</h1><p>Create and manage authorized CHO accounts.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><div class="panel-head"><h5>Add Staff Account</h5></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-3"><label>Staff ID *</label><input name="staff_id" class="form-control" required></div><div class="col-md-5"><label>Full Name *</label><input name="full_name" class="form-control" required></div><div class="col-md-4"><label>Email *</label><input name="email" type="email" class="form-control" required></div><div class="col-md-3"><label>Role *</label><select name="role_id" class="form-select" required><option value="">Select</option><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Service</label><select name="service_id" class="form-select"><option value="">None</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Professional Type</label><input name="professional_type" class="form-control"></div><div class="col-md-2"><label>License/PRC No.</label><input name="license_no" class="form-control"></div><div class="col-md-2"><label>Password *</label><input name="password" type="password" minlength="8" class="form-control" required></div><div class="col-12"><button class="btn btn-primary"><i class="bi bi-person-plus"></i> Create Account</button></div></form></div><div class="panel"><div class="panel-head"><h5>Staff Accounts</h5><input class="form-control table-search" placeholder="Search..." data-table-search="usersTable"></div><div class="table-responsive"><table class="table align-middle" id="usersTable"><thead><tr><th>Staff ID</th><th>Name</th><th>Role</th><th>Service</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['staff_id'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['role_name'])?></td><td><?=e($r['service_name']??'—')?></td><td><?=e($r['email'])?></td><td><span class="badge text-bg-<?= $r['status']==='Active'?'success':'secondary'?>"><?=e($r['status'])?></span></td><td><?php if(can('users.delete')):?><form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary"><?= $r['status']==='Active'?'Deactivate':'Activate'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
